mapper.select:
select conversation_id, visitor_id, scene, title, create_time, update_time
from ai_chat_conversation
where conversation_id = #{conversationId}

mapper.insert:
insert into ai_chat_conversation (
    conversation_id, visitor_id, scene, title, create_time, update_time
) values (
    #{conversationId}, #{visitorId}, #{scene}, #{title}, sysdate(), sysdate()
)

mapper.update:
update ai_chat_conversation
set update_time = sysdate()
where conversation_id = #{conversationId}

mapper.select:
select message_id, conversation_id, role, content, intent, intent_confidence,
       needs_clarification, sources_json, create_time
from ai_chat_message
where conversation_id = #{conversationId}
order by message_id desc
limit #{limit}

select count(*)
from ai_chat_message
where conversation_id = #{conversationId}
